# Check for rectangular regions of uniform color
def find_regions(grid, cell_size=5):
    """Find regions of uniform color defined by cell_size grid"""
    rows = len(grid)
    cols = len(grid[0])
    regions = {}

    for br in range(0, rows, cell_size):
        for bc in range(0, cols, cell_size):
            block = set()
            for r in range(br, min(br + cell_size, rows)):
                for c in range(bc, min(bc + cell_size, cols)):
                    block.add(grid[r][c])
            if len(block) == 1:
                # Uniform region
                color = list(block)[0]
                key = (br // cell_size, bc // cell_size)
                if color not in regions or key not in regions[color]:
                    regions.setdefault(color, {})[key] = (br, bc, min(br + cell_size, rows), min(bc + cell_size, cols))

    return regions

regions = find_regions(grid, cell_size=5)
print("Regions of uniform color (5x5 blocks):")
for color, block_keys in regions.items():
    print(f"\nColor {color}:")
    for key in block_keys:
        br, bc, er, ec = block_keys[key]
        print(f"  Block {key}: rows {br}-{er-1}, cols {bc}-{ec-1}")

