            tile = []
            for r in range(tr * tile_size, (tr + 1) * tile_size):
                tile.append(grid[r][tc * tile_size : (tc + 1) * tile_size])

            claimed = set()

            # Pattern 1: 15 fours - 3 consecutive uniform rows (all 5 cells same)
            for r_start in [0, 2]:
                rows = [r_start, r_start+1, r_start+2]
                # Check if each row is fully uniform
                all_rows_uniform = True
                target_color = None
                for r in rows:
                    row_val = tile[r][0]
                    if all(tile[r][c] == row_val for c in range(5)):
                        if target_color is None:
                            target_color = row_val
                    else:
                        all_rows_uniform = False
                        break

                if all_rows_uniform and target_color is not None:
                    for r in rows:
                        for c in range(5):
                            claimed.add((r, c))

            # Pattern 2: 9 fours - 3×3 at rows 2-4, cols 2-4
            if (2, 2) not in claimed:
                if all(tile[r][c] == tile[2][2] for r in range(2, 5) for c in range(2, 5)):
                    for r in range(2, 5):
                        for c in range(2, 5):
                            claimed.add((r, c))

            # Pattern 3: 6 fours - 3×2 or 2×6 uniform regions (cols 0-1)
            # Check 3×2 (rows 0-1, cols 0-1)
            if (0, 0) not in claimed and (0, 1) not in claimed:
                if all(tile[r][c] == tile[0][0] for r in range(2) for c in range(2)):
                    for r in range(2):
                        for c in range(2):
                            claimed.add((r, c))

            # Check 3×6 (rows 2-4, cols 0-1)  
            if (2, 0) not in claimed and (2, 1) not in claimed:
                if all(tile[r][c] == tile[2][0] for r in range(2, 5) for c in range(2)):
                    for r in range(2, 5):
                        for c in range(2):
                            claimed.add((r, c))

            # Check 3×6 (rows 0-2, cols 0-1)
            if (0, 0) not in claimed and (1, 0) not in claimed:
                if all(tile[r][c] == tile[0][0] for r in range(3) for c in range(2)):
                    for r in range(3):
                        for c in range(2):
                            claimed.add((r, c))

            # Pattern 4: 4 fours - 2×2 at rows 0-1, cols 0-1
            # Also check other 2×2 patterns for 4 fours
            for r_c_start, r_end, c_c_start, c_end in [(0,1,0,1)]:
