                           for r in range(r_c_start, r_end+1) 
                           for c in range(c_c_start, c_end+1)):
                        for r in range(r_c_start, r_end+1):
                            for c in range(c_c_start, c_end+1):
                                claimed.add((r, c))

            # Pattern 5: 3 fours - 3×1 in col 4
            for r_start in [0, 2]:
                if (r_start, 4) not in claimed and (r_start+1, 4) not in claimed and (r_start+2, 4) not in claimed:
